/*
 * Documentation-grade semantic C for the completed-Level-B Region-B DMA
 * late-arm boundary. This file is not matching source and is not a build
 * input. Exact opcodes, function hashes, xrefs and asset identities are
 * regenerated by tools/phase4_fmv_levelb_region_b_dma_subwindow.py.
 */
#include <stdint.h>

extern int CdRead(int sectors, void *destination, int mode);
extern int CdReadSync(int mode, void *result);
extern void copy_bytes(void *destination, const void *source, int length);

#define REGION_B_BASE ((void *)0x800B5788u)
#define MEMORY_BIN_BYTES 36448
#define CD_SECTOR_BYTES 2048

/*
 * The selected completed-Level-B continuation reaches E16 selector zero and
 * preserves Region-B destination 0x800B5788 through universal_file_loader.
 * file_lookup_cdsearchfile stores that destination in s3 at 0x80045FD4.
 *
 * The helper rounds the pristine 36,448-byte BITS/MEMORY.BIN extent to 18
 * sectors / 36,864 bytes. Before submission it copies the 416 bytes beyond
 * the logical destination end into scratch at 0x8009B890. After a successful
 * synchronous read it restores those bytes from scratch, undoing the rounded
 * read's overlap. Both copies are CPU operations, not CD-ROM DMA events.
 *
 * At 0x80046070 a0 receives the exact 18-sector count, 0x80046074 restores
 * a1 from s3, and 0x80046078 is the selected path's sole CdRead call. An
 * execute stop at 0x80046078 occurs before the JAL and its mode-setting delay
 * slot, so a transfer log armed at that paused boundary cannot miss this
 * submission and excludes all earlier FMV-stream traffic.
 *
 * The success path polls CdReadSync at 0x80046090 and joins the common
 * epilogue at 0x800460C4; the failed-submit path also joins 0x800460C4. A
 * second execute stop before 0x800460C4 therefore bounds one submission,
 * its synchronous wait and optional tail restore without admitting a later
 * universal-loader retry. Static code does not prove that the native read
 * succeeds or identify any DMA event, cycle, direction, LBA or result.
 */
static int selected_memory_bin_transfer(void)
{
    int sectors = (MEMORY_BIN_BYTES + CD_SECTOR_BYTES - 1) /
                  CD_SECTOR_BYTES;
    int padded_bytes = sectors * CD_SECTOR_BYTES;

    if (MEMORY_BIN_BYTES < padded_bytes)
        copy_bytes((void *)0x8009B890u,
                   (uint8_t *)REGION_B_BASE + MEMORY_BIN_BYTES,
                   padded_bytes - MEMORY_BIN_BYTES);

    if (!CdRead(sectors, REGION_B_BASE, 0x80))
        return 0;
    while (CdReadSync(1, 0) > 0) {
    }
    if (MEMORY_BIN_BYTES < padded_bytes)
        copy_bytes((uint8_t *)REGION_B_BASE + MEMORY_BIN_BYTES,
                   (const void *)0x8009B890u,
                   padded_bytes - MEMORY_BIN_BYTES);
    return MEMORY_BIN_BYTES;
}
